610	typedef struct dm_kb_state_s {
611	    lv_obj_t          *kb;           /* 键盘对象 */
612	    lv_obj_t          *ta;           /* 关联的 textarea */
613	    dm_kb_ready_cb_t   on_ready;     /* 回车回调（LV_EVENT_READY） */
