616	
617	/* 键盘隐藏/显示回调：textarea 聚焦→显示，失焦→隐藏 */
618	static void dm_kb_ta_focused_cb(lv_event_t *e)
619	{
620	    dm_kb_state_t *state = lv_event_get_user_data(e);
621	    if (state && state->kb)
622	        lv_obj_clear_flag(state->kb, LV_OBJ_FLAG_HIDDEN);
623	}
624	
625	static void dm_kb_ta_defocused_cb(lv_event_t *e)
626	{
627	    dm_kb_state_t *state = lv_event_get_user_data(e);
628	    if (!state || !state->kb)
629	        return;
630	    lv_obj_t *new_focus = lv_event_get_param(e);
631	    if (new_focus == state->kb || new_focus == state->ta)
632	        return;
633	    lv_obj_add_flag(state->kb, LV_OBJ_FLAG_HIDDEN);
634	}
635	
636	/* 键盘事件：回车→on_ready 回调，取消→隐藏 */
637	static void dm_kb_event_cb(lv_event_t *e)
638	{
639	    dm_kb_state_t *state = lv_event_get_user_data(e);
640	    if (!state)
641	        return;
642	    lv_event_code_t code = lv_event_get_code(e);
643	    if (code == LV_EVENT_READY) {
644	        if (state->on_ready)
645	            state->on_ready(state->ta, state->user_data);
646	    } else if (code == LV_EVENT_CANCEL) {
647	        lv_obj_add_flag(state->kb, LV_OBJ_FLAG_HIDDEN);
648	    }
649	}
