/* 键盘回车回调 / 发送按钮（dm_kb_ready_cb_t 签名）：
 * 发送 textarea 内容 + \r\n 换行，模拟终端回车 */
static void uart_dbg_send_ready_cb(lv_obj_t *ta, void *user_data)
{
    (void)user_data;
    reset_idle_timer();
    if (!ta)
        return;
    const char *txt = lv_textarea_get_text(ta);
    if (txt && txt[0]) {
        dm_uart_dbg_write(txt, (int)strlen(txt));
        LV_LOG_USER("[uart_dbg] sent %d bytes", (int)strlen(txt));
    }
    /* 追加 \r\n，对端收到完整命令行 */
    dm_uart_dbg_write("\r\n", 2);
    lv_textarea_set_text(ta, "");
}

